class Money:
    """An amount of money, stored as an integer number of cents."""

    def __init__(self, cents):
        self.cents = cents

    def __add__(self, other):
        return Money(self.cents + other.cents)

    def __eq__(self, other):
        return isinstance(other, Money) and self.cents == other.cents

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        return f'{sign}${abs(self.cents) / 100:,.2f}'

    def split(self, n):
        """Divide this amount into n shares whose sum is exactly self.cents.

        The indivisible remainder is handed out one cent at a time to the
        first shares, so no money is created or lost.
        """
        if n <= 0:
            raise ValueError('cannot split money into zero or fewer shares')
        share, remainder = divmod(self.cents, n)
        return [Money(share + 1 if i < remainder else share) for i in range(n)]
